export default "rvice = self.settings\\n\\n        access_token_expires = timedelta(seconds=settings_service.auth_settings.ACCESS_TOKEN_EXPIRE_SECONDS)\\n        access_token = self.create_token(\\n            data={\\\"sub\\\": str(user_id), \\\"type\\\": \\\"access\\\"},\\n            expires_delta=access_token_expires,\\n        )\\n\\n        refresh_token_expires = timedelta(seconds=settings_service.auth_settings.REFRESH_TOKEN_EXPIRE_SECONDS)\\n        refresh_token = self.create_token(\\n            data={\\\"sub\\\": str(user_id), \\\"type\\\": \\\"refresh\\\"},\\n            expires_delta=refresh_token_expires,\\n        )\\n\\n        if update_last_login:\\n            await update_user_last_login_at(user_id, db)\\n\\n        return {\\n            \\\"access_token\\\": access_token,\\n            \\\"refresh_token\\\": refresh_token,\\n            \\\"token_type\\\": \\\"bearer\\\",\\n        }\\n\\n    async def create_refresh_token(self, refresh_token: str, db: AsyncSession):\\n        from langflow.services.auth.utils import get_jwt_verification_key\\n\\n        settings_service = self.settings\\n\\n        algorithm = settings_service.auth_settings.ALGORITHM\\n        verification_key = get_jwt_verification_key(settings_service)\\n\\n        try:\\n            with warnings.catch_warnings():\\n                warnings.simplefilter(\\\"ignore\\\")\\n                payload = jwt.decode(\\n                    refresh_token,\\n                    verification_key,\\n                    algorithms=[algorithm],\\n                )\\n            user_id: UUID = payload.get(\\\"sub\\\")  # type: ignore[assignment]\\n            token_type: str = payload.get(\\\"type\\\")  # type: ignore[assignment]\\n\\n            if user_id is None or token_type != \\\"refresh\\\":  # noqa: S105\\n                raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"Invalid refresh token\\\")\\n\\n            user_exists = await get_user_by_id(db, user_id)\\n\\n            if user_exists is None:\\n                raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"Invalid refresh token\\\")\\n\\n            if not user_exists.is_active:\\n                raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"User account is inactive\\\")\\n\\n            return await self.create_user_tokens(user_id, db)\\n\\n        except InvalidTokenError as e:\\n            logger.exception(\\\"JWT decoding error\\\")\\n            raise HTTPException(\\n                status_code=status.HTTP_401_UNAUTHORIZED,\\n                detail=\\\"Invalid refresh token\\\",\\n            ) from e\\n\\n    async def authenticate_user(\\n        self, username: str, password: str, db: AsyncSession, request: Request | None = None\\n    ) -> User | None:\\n        user = await get_user_by_username(db, username)\\n\\n        if not user:\\n            if request and request.client:\\n                # Hash username for correlation without exposing PII\\n                username_hash = hashlib.sha256(username.lower().encode()).hexdigest()[:16]\\n                logger.warning(\\n                    \\\"Login failed: user not found\\\",\\n                    auth_event=\\\"login_failed\\\",\\n                    reason=\\\"user_not_found\\\",\\n                    username_hash=username_hash,\\n                    client_ip=request.client.host,\\n                )\\n            return None\\n\\n        if not user.is_active:\\n            if request and request.client:\\n                logger.warning(\\n                    \\\"Login failed: inactive user\\\",\\n                    auth_event=\\\"login_failed\\\",\\n                    reason=\\\"user_inactive\\\",\\n                    auth_id=str(user.id),\\n                    client_ip=request.client.host,\\n                )\\n            if not user.last_login_at:\\n                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Waiting for approval\\\")\\n            raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"Inactive user\\\")\\n\\n        auth_settings = self.settings.auth_settings\\n        auto_login_superuser = auth_settings.SUPERUSER or DEFAULT_SUPERUSER\\n        legacy_superuser_usernames = {DEFAULT_SUPERUSER, auto_login_superuser}\\n        if username in legacy_superuser_usernames and password == LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value():\\n            if request and request.client:\\n                logger.warning(\\n                    \\\"Login failed: legacy default superuser password is disabled\\\",\\n                    auth_event=\\\"login_failed\\\",\\n                    reason=\\\"legacy_default_password_disabled\\\",\\n                    auth_id=str(user.id),\\n                    client_ip=request.client.host,\\n                )\\n            return None\\n\\n        if not self.verify_password(password, user.password):\\n            if request and request.client:\\n                logger.warning(\\n                    \\\"Login failed: incorrect password\\\",\\n                    auth_event=\\\"login_failed\\\",\\n                    reason=\\\"incorrect_password\\\",\\n                    auth_id=str(user.id),\\n                    client_ip=request.client.host,\\n                )\\n            return None\\n\\n        # Successful login\\n        if request and request.client:\\n            logger.info(\\n                \\\"Login successful\\\",\\n                auth_event=\\\"login_success\\\",\\n                auth_id=str(user.id),\\n                client_ip=request.client.host,\\n            )\\n        return user\\n\\n    def _get_fernet(self) -> Fernet:\\n        from langflow.services.auth.utils import get_fernet\\n\\n        return get_fernet(self.settings)\\n\\n    def _get_decryption_fernet(self) -> Fernet | MultiFernet:\\n        from langflow.services.auth.utils import get_fernet_for_decryption\\n\\n        return get_fernet_for_decryption(self.settings)\\n\\n    def encrypt_api_key(self, api_key: str) -> str:\\n        fernet = self._get_fernet()\\n        encrypted_key = fernet.encrypt(api_key.encode())\\n        return encrypted_key.decode()\\n\\n    def decrypt_api_key(self, encrypted_api_key: str) -> str:\\n        \\\"\\\"\\\"Decrypt an encrypted API key.\\n\\n        Args:\\n            encrypted_api_key: The encrypted API key string\\n\\n        Returns:\\n            Decrypted API key string, or empty string if decryption fails\\n\\n        Note:\\n            - Returns empty string for invalid input (None, empty string)\\n            - Returns plaintext keys as-is (not starting with \\\"gAAAAA\\\")\\n            - Logs warnings on decryption failures for security monitoring\\n        \\\"\\\"\\\"\\n        if not isinstance(encrypted_api_key, str) or not encrypted_api_key:\\n            logger.debug(\\\"decrypt_api_key called with invalid input (empty or non-string)\\\")\\n            return \\\"\\\"\\n\\n        # Fernet tokens always start with \\\"gAAAAA\\\" - if not, return as-is (plain text)\\n        if not encrypted_api_key.startswith(\\\"gAAAAA\\\"):\\n            return encrypted_api_key\\n\\n        fernet = self._get_decryption_fernet()\\n        try:\\n            return fernet.decrypt(encrypted_api_key.encode()).decode()\\n        except Exception as primary_exception:  # noqa: BLE001\\n            logger.debug(\\n                \\\"Decryption using UTF-8 encoded API key failed. Error: %r. \\\"\\n                \\\"Retrying decryption using the raw string input.\\\",\\n                primary_exception,\\n            )\\n            try:\\n                return fernet.decrypt(encrypted_api_key).decode()\\n            except Exception as secondary_exception:  # noqa: BLE001\\n                # Decryption failed completely - log warning and return empty string\\n                logger.warning(\\n                    \\\"API key decryption failed after retry. This may indicate a corrupted key or \\\"\\n                    \\\"SECRET_KEY mismatch. Primary error: %r, Secondary error: %r\\\",\\n                    primary_exception,\\n                    secondary_exception,\\n                )\\n                return \\\"\\\"\\n\\n    async def get_current_user_mcp(\\n        self,\\n        token: str | Coroutine | None,\\n        query_param: str | None,\\n        header_param: str | None,\\n        db: AsyncSession,\\n    ) -> User | UserRead:\\n        clear_current_auth_context()\\n        clear_current_external_access_context()\\n        if token:\\n            return await self.get_current_user_from_access_token(token, db)\\n\\n        settings_service = self.settings\\n        result: User | None\\n        api_key_result = None\\n\\n        if settings_service.auth_settings.AUTO_LOGIN:\\n            if not settings_service.auth_settings.SUPERUSER:\\n                raise HTTPException(\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    detail=\\\"Missing first superuser credentials\\\",\\n                )\\n            if not query_param and not header_param:\\n                # AUTO_LOGIN parity with _api_key_security_impl / ws_api_key_security:\\n                # AUTO_LOGIN on its own is not a credential. Only an explicit\\n                # skip_auth_auto_login opt-in may resolve a credential-less caller to\\n                # the superuser; otherwise the MCP transport endpoints would accept\\n                # anonymous requests that every other authenticated route rejects.\\n                if not settings_service.auth_settings.skip_auth_auto_login:\\n                    raise HTTPException(\\n                        status_code=status.HTTP_403_FORBIDDEN,\\n                        detail=AUTO_LOGIN_ERROR,\\n                    )\\n                result = await get_user_by_username(db, settings_service.auth_settings.SUPERUSER)\\n                if result:\\n                    logger.warning(AUTO_LOGIN_WARNING)\\n                    set_current_auth_context(AuthCredentialContext(method=AUTH_METHOD_AUTO_LOGIN))\\n                    return result\\n            else:\\n                # At least one of query_param or header_param is truthy\\n                api_key = query_param or header_param\\n                if api_key is None:  # pragma: no cover - guaranteed by the if-condition above\\n                    raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=\\\"Invalid or missing API key\\\")\\n                api_key_result = await authenticate_api_key(api_key)\\n                result = api_key_result.user if api_key_result is not None else None\\n\\n        elif not query_param and not header_param:\\n            raise HTTPException(\\n                status_code=status.HTTP_403_FORBIDDEN,\\n                detail=\\\"An API key must be passed as query or header\\\",\\n            )\\n\\n        elif query_param:\\n            api_key_result = await authenticate_api_key(query_param)\\n            result = api_key_result.user if api_key_result is not None else None\\n\\n        else:\\n            # header_param must be truthy here (query_param is falsy, and we passed the not-both-None check)\\n            if header_param is None:  # pragma: no cover - guaranteed by the elif chain above\\n                raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=\\\"Invalid or missing API key\\\")\\n            api_key_result = await authenticate_api_key(header_param)\\n            result = api_key_result.user if api_key_result is not None else None\\n\\n        if not result:\\n            raise HTTPException(\\n                status_code=status.HTTP_403_FORBIDDEN,\\n                detail=\\\"Invalid or missing API key\\\",\\n            )\\n\\n        if isinstance(result, User):\\n            if api_key_result is not None:\\n                set_current_auth_context(AuthCredentialContext.from_api_key_result(api_key_result))\\n            return result\\n\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"Invalid authentication result\\\",\\n        )\\n\\n    async def get_current_active_user_mcp(self, current_user: User | UserRead) -> User | UserRead:\\n        if not current_user.is_active:\\n            raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"Inactive user\\\")\\n        set_current_model_provider_policy_context(\\n            user_id=current_user.id,\\n            attributes={\\\"is_superuser\\\": bool(current_user.is_superuser)},\\n        )\\n        return current_user\\n\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Teardown the auth service (no-op for JWT auth).\\\"\\\"\\\"\\n        logger.debug(\\\"Auth service teardown\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/auth/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d3d3bfa08af64f95b2ad4f2fe93ecfaad776f7e29976ac4bcd2124617103ea5b\",\"content\":\"from __future__ import annotations\\n\\nimport base64\\nimport hashlib\\nimport random\\nfrom typing import TYPE_CHECKING, Annotated, Final\\n\\nfrom cryptography.fernet import Fernet, MultiFernet\\nfrom fastapi import Depends, HTTPException, Request, Security, WebSocket, WebSocketException, status\\nfrom fastapi.security import APIKeyHeader, APIKeyQuery, OAuth2PasswordBearer\\nfrom fastapi.security.utils import get_authorization_scheme_param\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import injectable_session_scope, session_scope\\nfrom lfx.services.settings.constants import MINIMUM_SECRET_KEY_LENGTH\\n\\nfrom langflow.services.auth.exceptions import (\\n    AuthBackendUnavailableError,\\n    AuthenticationError,\\n    InsufficientPermissionsError,\\n    InvalidCredentialsError,\\n    MissingCredentialsError,\\n)\\nfrom langflow.services.auth.external import extract_external_token\\nfrom langflow.services.deps import get_auth_service, get_settings_service\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Coroutine\\n    from datetime import timedelta\\n\\n    from lfx.services.settings.service import SettingsService\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.database.models.user.model import User, UserRead\\n\\n\\nclass OAuth2PasswordBearerCookie(OAuth2PasswordBearer):\\n    \\\"\\\"\\\"Custom OAuth2 scheme that checks Authorization header first, then cookies.\\n\\n    This allows the application to work with HttpOnly cookies while supporting\\n    explicit Authorization headers for backward compatibility and testing scenarios.\\n    If an explicit Authorization header is provided, it takes precedence over cookies.\\n    When external trusted auth is enabled, the configured external header/cookie\\n    is consulted last so the native JWT path is always tried first.\\n    \\\"\\\"\\\"\\n\\n    async def __call__(self, request: Request) -> str | None:\\n        # First, check for explicit Authorization header (for backward compatibility and testing)\\n        authorization = request.headers.get(\\\"Authorization\\\")\\n        scheme, param = get_authorization_scheme_param(authorization)\\n        if scheme.lower() == \\\"bearer\\\" and param:\\n            return param\\n\\n        # Fall back to cookie (for HttpOnly cookie support in browser-based clients)\\n        token = request.cookies.get(\\\"access_token_lf\\\")\\n        if token:\\n            return token\\n\\n        # Final fallback: external trusted credential (validated downstream).\\n        if external := _get_external_token(request.headers, request.cookies):\\n            return external\\n\\n        # If auto_error is True, this would raise an exception\\n        # Since we set auto_error=False, return None\\n        return None\\n\\n\\ndef _get_external_token(headers, cookies) -> str | None:\\n    \\\"\\\"\\\"Return the configured external credential, swallowing transient failures.\\\"\\\"\\\"\\n    try:\\n        auth_settings = get_settings_service().auth_settings\\n    except Exception:  # noqa: BLE001\\n        return None\\n    return extract_external_token(headers, cookies, auth_settings)\\n\\n\\noauth2_login = OAuth2PasswordBearerCookie(tokenUrl=\\\"api/v1/login\\\", auto_error=False)\\n\\nAPI_KEY_NAME = \\\"x-api-key\\\"\\n\\napi_key_query = APIKeyQuery(name=API_KEY_NAME, scheme_name=\\\"API key query\\\", auto_error=False)\\napi_key_header = APIKeyHeader(name=API_KEY_NAME, scheme_name=\\\"API key header\\\", auto_error=False)\\n\\n\\ndef _auth_service():\\n    \\\"\\\"\\\"Return the currently configured auth service.\\n\\n    This is an internal helper to keep imports local to the auth services layer.\\n    **New code should prefer calling `get_auth_service()` directly** instead of\\n    using this helper or adding new thin wrapper functions here.\\n    \\\"\\\"\\\"\\n    return get_auth_service()\\n\\n\\nREFRESH_TOKEN_TYPE: Final[str] = \\\"refresh\\\"  # noqa: S105\\nACCESS_TOKEN_TYPE: Final[str] = \\\"access\\\"  # noqa: S105\\n\\n# JWT key configuration error messages\\nPUBLIC_KEY_NOT_CONFIGURED_ERROR: Final[str] = (\\n    \\\"Server configuration error: Public key not configured for asymmetric JWT algorithm.\\\"\\n)\\nSECRET_KEY_NOT_CONFIGURED_ERROR: Final[str] = \\\"Server configuration error: Secret key not configured.\\\"  # noqa: S105\\n\\n\\nclass JWTKeyError(HTTPException):\\n    \\\"\\\"\\\"Raised when JWT key configuration is invalid.\\\"\\\"\\\"\\n\\n    def __init__(self, detail: str, *, include_www_authenticate: bool = True):\\n        headers = {\\\"WWW-Authenticate\\\": \\\"Bearer\\\"} if include_www_authenticate else None\\n        super().__init__(\\n            status_code=status.HTTP_401_UNAUTHORIZED,\\n            detail=detail,\\n            headers=headers,\\n        )\\n\\n\\ndef get_jwt_verification_key(settings_service: SettingsService) -> str:\\n    \\\"\\\"\\\"Get the appropriate key for JWT verification based on configured algorithm.\\n\\n    For asymmetric algorithms (RS256, RS512): returns public key\\n    For symmetric algorithms (HS256): returns secret key\\n    \\\"\\\"\\\"\\n    algorithm = settings_service.auth_settings.ALGORITHM\\n\\n    if algorithm.is_asymmetric():\\n        verification_key = settings_service.auth_settings.PUBLIC_KEY\\n        if not verification_key:\\n            logger.error(\\\"Public key is not set in settings for RS256/RS512.\\\")\\n            raise JWTKeyError(PUBLIC_KEY_NOT_CONFIGURED_ERROR)\\n        return verification_key\\n\\n    secret_key = settings_service.auth_settings.SECRET_KEY.get_secret_value()\\n    if secret_key is None:\\n        logger.error(\\\"Secret key is not set in settings.\\\")\\n        raise JWTKeyError(SECRET_KEY_NOT_CONFIGURED_ERROR)\\n    return secret_key\\n\\n\\ndef get_jwt_signing_key(settings_service: SettingsService) -> str:\\n    \\\"\\\"\\\"Get the appropriate key for JWT signing based on configured algorithm.\\n\\n    For asymmetric algorithms (RS256, RS512): returns private key\\n    For symmetric algorithms (HS256): returns secret key\\n    \\\"\\\"\\\"\\n    algorithm = settings_service.auth_settings.ALGORITHM\\n\\n    if algorithm.is_asymmetric():\\n        return settings_service.auth_settings.PRIVATE_KEY.get_secret_value()\\n\\n    return settings_service.auth_settings.SECRET_KEY.get_secret_value()\\n\\n\\nasync def api_key_security(\\n    query_param: Annotated[str | None, Security(api_key_query)],\\n    header_param: Annotated[str | None, Security(api_key_header)],\\n) -> UserRead | None:\\n    return await _auth_service().api_key_security(query_param, header_param)\\n\\n\\nasync def ws_api_key_security(api_key: str | None) -> UserRead:\\n    return await _auth_service().ws_api_key_security(api_key)\\n\\n\\ndef _auth_error_to_http(e: AuthenticationError) -> HTTPException:\\n    \\\"\\\"\\\"Map auth exceptions to 503 Service Unavailable, 403 Forbidden or 401 Unauthorized.\\n\\n    Langflow returns 403 for missing/invalid credentials; 401 for invalid/expired tokens.\\n    A backend failure never judged the credential, so it is reported as a\\n    retryable 503 rather than as a verdict on the caller's token.\\n    \\\"\\\"\\\"\\n    if isinstance(e, AuthBackendUnavailableError):\\n        return HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail=e.message,\\n            headers={\\\"Retry-After\\\": \\\"1\\\"},\\n        )\\n    if isinstance(\\n        e,\\n        (MissingCredentialsError, InvalidCredentialsError, InsufficientPermissionsError),\\n    ):\\n        return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=e.message)\\n    return HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=e.message)\\n\\n\\nasync def get_current_user(\\n    request: Request,\\n    token: Annotated[str | None, Security(oauth2_login)],\\n    query_param: Annotated[str | None, Security(api_key_query)],\\n    header_param: Annotated[str | None, Security(api_key_header)],\\n    db: AsyncSession = Depends(injectable_session_scope, scope=\\\"function\\\"),\\n) -> User:\\n    # Keep the native token (resolved by oauth2_login, which may already have\\n    # collapsed to the external credential) separate from a freshly-extracted\\n    # external credential so a present-but-invalid native cookie cannot shadow a\\n    # valid external one. The auth service tries the native token first and only\\n    # falls back to the external credential when it differs from the token.\\n    external_token = _get_external_token(request.headers, request.cookies)\\n    try:\\n        return await _auth_service().get_current_user(\\n            token, query_param, header_param, db, external_token=external_token\\n        )\\n    except AuthenticationError as e:\\n        raise _auth_error_to_http(e) from e\\n\\n\\nasync def get_current_user_from_access_token(\\n    token: str | Coroutine | None,\\n    db: AsyncSession,\\n    external_token: str | None = None,\\n) -> User:\\n    \\\"\\\"\\\"Compatibility helper to resolve a user from an access token.\\n\\n    This simply delegates to the active auth service's\\n    `get_current_user_from_access_token` implementation. ``external_token`` is an\\n    optional, separately-extracted external credential tried as a fallback when\\n    native token authentication fails; when ``None`` behavior is unchanged.\\n\\n    **For new code, prefer calling\\n    `get_auth_service().get_current_user_from_access_token(...)` directly**\\n    instead of importing this function.\\n    \\\"\\\"\\\"\\n    try:\\n        return await _auth_service().get_current_user_from_access_token(token, db, external_token=external_token)\\n    except AuthenticationError as e:\\n        raise _auth_error_to_http(e) from e\\n\\n\\nWS_AUTH_REASON = \\\"Missing or invalid credentials (cookie, token or API key).\\\"\\n\\n\\nasync def get_current_user_for_websocket(\\n    websocket: WebSocket,\\n    db: AsyncSession,\\n) -> User | UserRead:\\n    \\\"\\\"\\\"Extracts credentials from WebSocket and delegates to auth service.\\\"\\\"\\\"\\n    # Keep the native token and the external credential separate so a present but\\n    # invalid/expired native token cannot shadow a valid external credential; the\\n    # auth service tries the external token as a fallback when native auth fails.\\n    token = websocket.cookies.get(\\\"access_token_lf\\\") or websocket.query_params.get(\\\"token\\\")\\n    external_token = _get_external_token(websocket.headers, websocket.cookies)\\n    api_key = (\\n        websocket.query_params.get(\\\"x-api-key\\\")\\n        or websocket.query_params.get(\\\"api_key\\\")\\n        or websocket.headers.get(\\\"x-api-key\\\")\\n        or websocket.headers.get(\\\"api_key\\\")\\n    )\\n\\n    try:\\n        return await _auth_service().get_current_user_for_websocket(token, api_key, db, external_token=external_token)\\n    except AuthBackendUnavailableError as e:\\n        # The credential was never judged, so closing as a policy violation\\n        # would tell the client to fix a credential that is not the problem.\\n        raise WebSocketException(code=status.WS_1013_TRY_AGAIN_LATER, reason=e.message) from e\\n    except AuthenticationError as e:\\n        raise WebSocketException(code=status.WS_1008_POLICY_VIOLATION, reason=WS_AUTH_REASON) from e\\n\\n\\nasync def get_current_user_for_sse(\\n    request: Request,\\n    db: AsyncSession = Depends(injectable_session_scope, scope=\\\"function\\\"),\\n) -> User | UserRead:\\n    \\\"\\\"\\\"Extracts credentials from request and delegates to auth service.\\n\\n    Accepts cookie (access_token_lf) or API key (x-api-key query param).\\n    \\\"\\\"\\\"\\n    # Keep the native token and the external credential separate (see\\n    # get_current_user_for_websocket) so the external credential remains a usable\\n    # fallback even when a stale native cookie is present.\\n    token = request.cookies.get(\\\"access_token_lf\\\")\\n    external_token = _get_external_token(request.headers, request.cookies)\\n    api_key = request.query_params.get(\\\"x-api-key\\\") or request.headers.get(\\\"x-api-key\\\")\\n\\n    try:\\n        return await _auth_service().get_current_user_for_sse(token, api_key, db, external_token=external_token)\\n    except AuthBackendUnavailableError as e:\\n        raise _auth_error_to_http(e) from e\\n    except AuthenticationError as e:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"Missing or invalid credentials (cookie or API key).\\\",\\n        ) from e\\n\\n\\nasync def get_current_user_for_workflow(\\n    token: Annotated[str | None, Security(oauth2_login)],\\n    query_param: Annotated[str | None, Security(api_key_query)],\\n    header_param: Annotated[str | None, Security(api_key_header)],\\n) -> UserRead:\\n    \\\"\\\"\\\"Combined session-or-API-key auth that does not hold a DB session.\\n\\n    Resolves the user from a session cookie/token *or* an API key inside a\\n    short-lived session that is committed and closed before the path operation\\n    runs. Unlike `get_current_active_user` (a generator dependency whose session\\n    stays open for the whole request), this is required by endpoints that\\n    execute a graph inline: a held auth connection contends with the run's own\\n    writes (on SQLite it blocks the run's INSERTs with \\\"database is locked\\\").\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.user.model import UserRead\\n\\n    async with session_scope() as db:\\n        try:\\n            user = await _auth_service().get_current_user(token, query_param, header_param, db)\\n        except AuthenticationError as e:\\n            raise _auth_error_to_http(e) from e\\n        active_user = await _auth_service().get_current_active_user(user)\\n        if active_user is None:\\n            raise HTTPException(\\n                status_code=status.HTTP_403_FORBIDDEN,\\n                detail=\\\"User account is inactive\\\",\\n            )\\n        return UserRead.model_validate(active_user, from_attributes=True)\\n\\n\\nasync def get_optional_user(\\n    token: Annotated[str | None, Security(oauth2_login)],\\n    query_param: Annotated[str | None, Security(api_key_query)],\\n    header_param: Annotated[str | None, Security(api_key_header)],\\n    db: AsyncSession = Depends(injectable_session_scope, scope=\\\"function\\\"),\\n) -> User | None:\\n    \\\"\\\"\\\"Get the current user if authenticated, otherwise return None.\\n\\n    This is useful for endpoints that need to behave differently for authenticated\\n    vs unauthenticated users (e.g., returning different response types).\\n\\n    Returns:\\n        User | None: The authenticated user if valid credentials are provided, None otherwise.\\n    \\\"\\\"\\\"\\n    try:\\n        user = await _auth_service().get_current_user(token, query_param, header_param, db)\\n    except (AuthenticationError, HTTPException):\\n        return None\\n    else:\\n        if user and user.is_active:\\n            return user\\n        return None\\n\\n\\nasync def get_webhook_user(flow_id: str, request: Request) -> UserRead:\\n    \\\"\\\"\\\"Get the user for webhook execution.\\n\\n    When WEBHOOK_AUTH_ENABLE=false, allows execution as the flow owner without API key.\\n    When WEBHOOK_AUTH_ENABLE=true, requires API key authentication and validates flow ownership.\\n\\n    Args:\\n        flow_id: The ID of the flow being executed\\n        request: The FastAPI request object\\n\\n    Returns:\\n        UserRead: The user to execute the webhook as\\n\\n    Raises:\\n        HTTPException: If authentication fails or user doesn't have permission\\n    \\\"\\\"\\\"\\n    return await _auth_service().get_webhook_user(flow_id, request)\\n\\n\\nasync def get_current_user_optional(\\n    request: Request,\\n    db: AsyncSession = Depends(injectable_session_scope, scope=\\\"function\\\"),\\n) -> User | None:\\n    \\\"\\\"\\\"Resolve the current user if authenticated, otherwise return None.\\n\\n    Checks HttpOnly cookie (access_token_lf), Authorization header, and API key.\\n    Used by endpoints that support both authenticated and unauthenticated access.\\n    \\\"\\\"\\\"\\n    token = request.cookies.get(\\\"access_token_lf\\\")\\n    api_key = request.query_params.get(\\\"x-api-key\\\") or request.headers.get(\\\"x-api-key\\\")\\n    auth_header = request.headers.get(\\\"Authorization\\\")\\n    if auth_header and auth_header.startswith(\\\"Bearer \\\"):\\n        token = token or auth_header[len(\\\"Bearer \\\") :]\\n\\n    # Keep the external credential separate so it remains a usable fallback when a\\n    # stale/invalid native token is present (see get_current_user_for_websocket).\\n    external_token = _get_external_token(request.headers, request.cookies)\\n\\n    if not token and not external_token and not api_key:\\n        return None\\n\\n    try:\\n        return await _auth_service().get_current_user_for_sse(token, api_key, db, external_token=external_token)\\n    except (AuthenticationError, HTTPException):\\n        return None\\n\\n\\nasync def get_current_active_user(user: User = Depends(get_current_user)) -> User | UserRead:\\n    result = await _auth_service().get_current_active_user(user)\\n    if result is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"User account is inactive\\\",\\n        )\\n    return result\\n\\n\\nasync def get_current_active_superuser(user: User = Depends(get_current_user)) -> User | UserRead:\\n    result = await _auth_service().get_current_active_superuser(user)\\n    if result is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"The user doesn't have enough privileges\\\",\\n        )\\n    return result\\n\\n\\ndef add_base64_padding(value: str) -> str:\\n    \\\"\\\"\\\"Add base64 padding characters if needed.\\n\\n    Base64 strings must have a length that is a multiple of 4.\\n    This adds the necessary '=' padding characters.\\n    \\\"\\\"\\\"\\n    remainder = len(value) % 4\\n    if remainder == 0:\\n        return value\\n    return value + \\\"=\\\" * (4 - remainder)\\n\\n\\ndef ensure_fernet_key(secret_key: str) -> bytes:\\n    \\\"\\\"\\\"Derive a valid Fernet key from a secret key string.\\n\\n    For short keys (< 32 chars), the 32-byte key is derived with SHA-256, a\\n    cryptographic hash. For longer keys, base64 padding is added.\\n\\n    Security note: short keys previously seeded Python's ``random`` module to\\n    generate key bytes. New encryption uses SHA-256 so it never depends on a\\n    non-cryptographic PRNG or mutates global PRNG state. Short, guessable input\\n    remains unsuitable for production; settings validation warns operators.\\n    \\\"\\\"\\\"\\n    if len(secret_key) < MINIMUM_SECRET_KEY_LENGTH:\\n        digest = hashlib.sha256(secret_key.encode()).digest()  # 32 bytes\\n        key = base64.urlsafe_b64encode(digest)\\n    else:\\n        key = add_base64_padding(secret_key).encode()\\n    return key\\n\\n\\ndef _ensure_legacy_fernet_key(secret_key: str) -> bytes:\\n    \\\"\\\"\\\"Reproduce the pre-1.10.1 short-secret key for decryption only.\\n\\n    This compatibility key must never be used for encryption. A local PRNG\\n    instance reproduces the legacy bytes without mutating global random state.\\n    \\\"\\\"\\\"\\n    legacy_random = random.Random(secret_key)  # noqa: S311\\n    legacy_bytes = bytes(legacy_random.getrandbits(8) for _ in range(32))\\n    return base64.urlsafe_b64encode(legacy_bytes)\\n\\n\\ndef get_fernet(settings_service: SettingsService) -> Fernet:\\n    \\\"\\\"\\\"Get the current Fernet instance used for encryption and decryption.\\\"\\\"\\\"\\n    secret_key: str = settings_service.auth_settings.SECRET_KEY.get_secret_value()\\n    return Fernet(ensure_fernet_key(secret_key))\\n\\n\\ndef get_fernet_for_decryption(settings_service: SettingsService) -> Fernet | MultiFernet:\\n    \\\"\\\"\\\"Get a Fernet-compatible instance that can read legacy ciphertext.\\n\\n    Args:\\n        settings_service: Settings service to get the secret key\\n\\n    Returns:\\n        For short secrets, MultiFernet with the current key first and the\\n        pre-1.10.1 key second. This function is used only for decryption; all\\n        encryption goes through :func:`get_fernet` and the current key.\\n    \\\"\\\"\\\"\\n    secret_key: str = settings_service.auth_settings.SECRET_KEY.get_secret_value()\\n    current_fernet = get_fernet(settings_service)\\n    if len(secret_key) >= MINIMUM_SECRET_KEY_LENGTH:\\n        return current_fernet\\n\\n    legacy_fernet = Fernet(_ensure_legacy_fernet_key(secret_key))\\n    return MultiFernet([current_fernet, legacy_fernet])\\n\\n\\ndef encrypt_api_key(api_key: str, settings_service: SettingsService | None = None) -> str:  # noqa: ARG001\\n    return _auth_service().encrypt_api_key(api_key)\\n\\n\\ndef decrypt_api_key(\\n    encrypted_api_key: str,\\n    settings_service: SettingsService | None = None,  # noqa: ARG001\\n) -> str:\\n    return _auth_service().decrypt_api_key(encrypted_api_key)\\n\\n\\ndef verify_password(plain_password: str, hashed_password: str) -> bool:\\n    return _auth_service().verify_password(plain_password, hashed_password)\\n\\n\\ndef get_password_hash(password: str) -> str:\\n    return _auth_service().get_password_hash(password)\\n\\n\\ndef create_token(data: dict, expires_delta: timedelta) -> str:\\n    \\\"\\\"\\\"Create a JWT token. Delegates to the active auth service.\\\"\\\"\\\"\\n    return _auth_service().create_token(data, expires_delta)\\n\\n\\nasync def create_refresh_token(refresh_token: str, db: AsyncSession) -> dict:\\n    \\\"\\\"\\\"Exchange a refresh token for new access/refresh tokens. Delegates to the active auth service.\\\"\\\"\\\"\\n    return await _auth_service().create_refresh_token(refresh_token, db)\\n\\n\\nasync def create_super_user(username: str, password: str, db: AsyncSession) -> User:\\n    return await _auth_service().create_super_user(username, password, db)\\n\\n\\nasync def create_user_longterm_token(db: AsyncSession) -> tuple:\\n    return await _auth_service().create_user_longterm_token(db)\\n\\n\\nasync def get_current_user_mcp(\\n    token: Annotated[str | None, Security(oauth2_login)],\\n    query_param: Annotated[str | None, Security(api_key_query)],\\n    header_param: Annotated[str | None, Security(api_key_header)],\\n    db: AsyncSession = Depends(injectable_session_scope, scope=\\\"function\\\"),\\n) -> User:\\n    try:\\n        return await _auth_service().get_current_user_mcp(token, query_param, header_param, db)\\n    except AuthenticationError as e:\\n        raise _auth_error_to_http(e) from e\\n\\n\\nasync def get_current_active_user_mcp(user: User = Depends(get_current_user_mcp)) -> User:\\n    return await _auth_service().get_current_active_user_mcp(user)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c7733c7c929fce4dccbed6930fedfbbce7416472082d72e85ca45aa98c39fc12\",\"content\":\"\\\"\\\"\\\"OSS authorization service package (pass-through default; plugins enforce).\\\"\\\"\\\"\\n\\nfrom langflow.services.authorization.actions import (\\n    DeploymentAction,\\n    FileAction,\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ProjectAction,\\n    ProviderAccountAction,\\n    ShareAction,\\n    VariableAction,\\n    VoiceAction,\\n)\\nfrom langflow.services.authorization.audit import (\\n    AuditPersistenceError,\\n    audit_decision,\\n    drain_pending_audit_writes,\\n    get_audit_producer_health,\\n)\\nfrom langflow.services.authorization.decorators import requires_flow_permission, requires_resource_permission\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped, deny_to_404\\nfrom langflow.services.authorization.guards import (\\n    capability_probe,\\n    ensure_deployment_permission,\\n    ensure_file_permission,\\n    ensure_flow_permission,\\n    ensure_flows_permission,\\n    ensure_knowledge_base_permission,\\n    ensure_permission,\\n    ensure_project_permission,\\n    ensure_provider_account_permission,\\n    ensure_share_permission,\\n    ensure_variable_permission,\\n    ensure_voice_permission,\\n    should_apply_owner_override,\\n)\\nfrom langflow.services.authorization.listing import (\\n    apply_owned_or_visible_prefilter,\\n    apply_owned_or_visible_scope_prefilter,\\n    filter_visible_resources,\\n    resource_visible_in_scope,\\n    restrict_to_owned_or_visible,\\n    restrict_to_owned_or_visible_scope,\\n    visible_id_prefilter,\\n    visible_scope_prefilter,\\n)\\nfrom langflow.services.authorization.service import LangflowAuthorizationService\\n\\n__all__ = [\\n    \\\"AuditPersistenceError\\\",\\n    \\\"DeploymentAction\\\",\\n    \\\"FileAction\\\",\\n    \\\"FlowAction\\\",\\n    \\\"KnowledgeBaseAction\\\",\\n    \\\"LangflowAuthorizationService\\\",\\n    \\\"ProjectAction\\\",\\n    \\\"ProviderAccountAction\\\",\\n    \\\"ShareAction\\\",\\n    \\\"VariableAction\\\",\\n    \\\"VoiceAction\\\",\\n    \\\"apply_owned_or_visible_prefilter\\\",\\n    \\\"apply_owned_or_visible_scope_prefilter\\\",\\n    \\\"audit_decision\\\",\\n    \\\"authorized_or_owner_scoped\\\",\\n    \\\"capability_probe\\\",\\n    \\\"deny_to_404\\\",\\n    \\\"drain_pending_audit_writes\\\",\\n    \\\"ensure_deployment_permission\\\",\\n    \\\"ensure_file_permission\\\",\\n    \\\"ensure_flow_permission\\\",\\n    \\\"ensure_flows_permission\\\",\\n    \\\"ensure_knowledge_base_permission\\\",\\n    \\\"ensure_permission\\\",\\n    \\\"ensure_project_permission\\\",\\n    \\\"ensure_provider_account_permission\\\",\\n    \\\"ensure_share_permission\\\",\\n    \\\"ensure_variable_permission\\\",\\n    \\\"ensure_voice_permission\\\",\\n    \\\"filter_visible_resources\\\",\\n    \\\"get_audit_producer_health\\\",\\n    \\\"requires_flow_permission\\\",\\n    \\\"requires_resource_permission\\\",\\n    \\\"resource_visible_in_scope\\\",\\n    \\\"restrict_to_owned_or_visible\\\",\\n    \\\"restrict_to_owned_or_visible_scope\\\",\\n    \\\"should_apply_owner_override\\\",\\n    \\\"visible_id_prefilter\\\",\\n    \\\"visible_scope_prefilter\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/access_ceiling.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eea54ececc27f8a1f4591e9445a3956f66c3555205d302ddd6d5bfbeb4f276ba\",\"content\":\"\\\"\\\"\\\"Request-scoped action ceiling (deny-only) enforced by authorization guards.\\n\\nThis is an authorization primitive: a coarse, deny-only cap on which actions a\\nrequest may perform, stored in a context variable for the lifetime of the\\nrequest/task. The authentication layer derives the ceiling from a trusted\\nexternal identity (see\\n``langflow.services.auth.external.access_context_from_identity``) and installs\\nit via :func:`set_current_external_access_context`; the guards in this package\\nconsult it. Keeping the primitive here lets authorization enforce the ceiling\\nwithout importing the authentication layer, preserving the auth/authz split\\ndocumented in AGENTS.md.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextvars import ContextVar\\nfrom dataclasses import dataclass\\n\\nEXTERNAL_ACCESS_VIEWER = \\\"viewer\\\"\\nEXTERNAL_ACCESS_EDITOR = \\\"editor\\\"\\nEXTERNAL_ACCESS_ADMIN = \\\"admin\\\"\\nEXTERNAL_ACCESS_LEVELS = frozenset(\\n    {\\n        EXTERNAL_ACCESS_VIEWER,\\n        EXTERNAL_ACCESS_EDITOR,\\n        EXTERNAL_ACCESS_ADMIN,\\n    }\\n)\\n# Action ceilings per external access level (deny-only caps):\\n#   viewer -> {read}\\n#   editor -> viewer + {write, create, delete, execute, ingest}\\n#   admin  -> all actions (no ceiling)\\n# ``deploy`` is intentionally admin-only and is therefore excluded from the\\n# editor set: an editor cannot promote a flow to a deployment.\\n_VIEWER_ALLOWED_ACTIONS = frozenset({\\\"read\\\"})\\n_EDITOR_ALLOWED_ACTIONS = frozenset({\\\"read\\\", \\\"write\\\", \\\"create\\\", \\\"delete\\\", \\\"execute\\\", \\\"ingest\\\"})\\n\\n\\n@dataclass(frozen=True)\\nclass ExternalAccessContext:\\n    \\\"\\\"\\\"Request-local access ceiling derived from an external identity claim.\\\"\\\"\\\"\\n\\n    provider: str\\n    subject: str\\n    level: str\\n    claim_name: str | None = None\\n    claim_value: str | None = None\\n\\n\\n_current_external_access: ContextVar[ExternalAccessContext | None] = ContextVar(\\n    \\\"langflow_external_access\\\",\\n    default=None,\\n)\\n\\n\\ndef set_current_external_access_context(context: ExternalAccessContext | None) -> None:\\n    \\\"\\\"\\\"Store the external access ceiling for the current request/task.\\\"\\\"\\\"\\n    _current_external_access.set(context)\\n\\n\\ndef clear_current_external_access_context() -> None:\\n    \\\"\\\"\\\"Clear any external access ceiling from the current request/task.\\\"\\\"\\\"\\n    _current_external_access.set(None)\\n\\n\\ndef get_current_external_access_context() -> ExternalAccessContext | None:\\n    \\\"\\\"\\\"Return the external access ceiling for the current request/task, if any.\\\"\\\"\\\"\\n    return _current_external_access.get()\\n\\n\\ndef external_access_allows(action: str, context: ExternalAccessContext | None = None) -> bool:\\n    \\\"\\\"\\\"Return whether the external access ceiling allows this action.\\n\\n    This is deliberately action-level and deny-only. It does not grant access to\\n    resources; normal ownership, route guards, and enterprise authz plugins still\\n    decide whether an otherwise allowed action may proceed.\\n    \\\"\\\"\\\"\\n    context = context if context is not None else get_current_external_access_context()\\n    if context is None:\\n        return True\\n\\n    normalized_action = action.strip().lower()\\n    if context.level == EXTERNAL_ACCESS_ADMIN:\\n        return True\\n    if context.level == EXTERNAL_ACCESS_EDITOR:\\n        return normalized_action in _EDITOR_ALLOWED_ACTIONS\\n    return normalized_action in _VIEWER_ALLOWED_ACTIONS\\n\\n\\ndef filter_actions_by_external_access_ceiling(actions: list[str] | tuple[str, ...]) -> list[str]:\\n    \\\"\\\"\\\"Filter an action list through the current external access ceiling.\\\"\\\"\\\"\\n    context = get_current_external_access_context()\\n    if context is None:\\n        return list(actions)\\n    return [action for action in actions if external_access_allows(action, context)]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/actions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30f9c2dbcf0a8786789bd8a9d0b3b2ed62f47ba5009c73199bdcdddee174e91e\",\"content\":\"\\\"\\\"\\\"Canonical authorization action vocabulary.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom enum import Enum\\n\\n\\nclass FlowAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a flow resource.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n    EXECUTE = \\\"execute\\\"\\n    DEPLOY = \\\"deploy\\\"\\n\\n\\nclass DeploymentAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a deployment resource.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n    EXECUTE = \\\"execute\\\"\\n\\n\\nclass ProjectAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a project (folder) resource.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n\\n\\nclass KnowledgeBaseAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a knowledge base resource.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n    INGEST = \\\"ingest\\\"\\n\\n\\nclass VariableAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a variable resource.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n\\n\\nclass FileAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a user-file resource (v2 files).\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n\\n\\nclass ProviderAccountAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on a deployment provider credential account.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    WRITE = \\\"write\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n\\n\\nclass VoiceAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on credential-backed voice resources.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n\\n\\nclass ShareAction(str, Enum):\\n    \\\"\\\"\\\"Actions authorized on an authz_share row.\\\"\\\"\\\"\\n\\n    READ = \\\"read\\\"\\n    CREATE = \\\"create\\\"\\n    DELETE = \\\"delete\\\"\\n    UPDATE = \\\"update\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/audit.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b3f498e6cf2cdde87b553059c6cf674034241861fb061937059a9c44bcb57417\",\"content\":\"\\\"\\\"\\\"Batched audit pipeline for authorization decisions.\\n\\nAn earlier revision did ``asyncio.create_task(_write())`` per authorization\\ndecision, with each write opening its own ``session_scope()``. That works on\\nlight traffic, but on a real workload (every authenticated request emits at\\nleast one audit row) it turns into a connection-pool storm.\\n\\nThis module routes every decision through a bounded queue drained by a\\nsingle long-lived writer task. The writer batches up to ``_AUDIT_BATCH_MAX``\\nrows per ``session_scope()`` and commits them in one INSERT. By default,\\n``audit_decision`` remains best effort and non-blocking. Operators that need\\ndelivery guarantees can opt into durable mode: the bounded queue then applies\\nbackpressure and the call returns only after its row's batch commits.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport time\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID, uuid4\\n\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.services.auth.context import (\\n    AUTH_METHOD_API_KEY,\\n    current_auth_context_for_audit,\\n    get_current_auth_context,\\n)\\nfrom langflow.services.deps import get_settings_service\\n\\nif TYPE_CHECKING:\\n    from lfx.services.authorization import AuthorizationPrincipal\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n# Shared audit result vocabulary.\\nAUDIT_ALLOW = \\\"allow\\\"\\nAUDIT_DENY = \\\"deny\\\"\\nAUDIT_OWNER_OVERRIDE = \\\"owner_override\\\"\\nAUDIT_SKIP = \\\"skip\\\"\\n\\nAUDIT_ACTOR_API_KEY = \\\"api_key\\\"  # pragma: allowlist secret\\nAUDIT_ACTOR_UNKNOWN = \\\"unknown\\\"\\nAUDIT_ACTOR_USER = \\\"user\\\"\\n\\n# ``details[\\\"event\\\"]`` discriminates the two row classes that share this table.\\n# Guards emit a row for every authorization *decision* they make; routes emit a\\n# second row after the effect is durable. Both used to be written under the same\\n# action name (``share:create`` for the check and for the created share), so a\\n# check and a real mutation were indistinguishable downstream. Readers that need\\n# \\\"what actually happened\\\" filter on ``AUDIT_EVENT_MUTATION``.\\nAUDIT_EVENT_DECISION = \\\"authorization_decision\\\"\\nAUDIT_EVENT_MUTATION = \\\"mutation\\\"\\n# Two further classes exist so that *every* row can be classified. Without them\\n# a reader filtering on ``event`` silently drops the untagged rows: reading the\\n# audit log itself, and the reconcile the server runs at startup with no user\\n# behind it. ``access`` is something a user did that changed nothing; ``system``\\n# is something the server did on its own.\\nAUDIT_EVENT_ACCESS = \\\"access\\\"\\nAUDIT_EVENT_SYSTEM = \\\"system\\\"\\n\\n_AUDIT_QUEUE_MAX = 10_000\\n_AUDIT_BATCH_MAX = 100\\n\\n# Minimum seconds between drop warnings while saturation persists.\\n_AUDIT_DROP_WARN_INTERVAL = 10.0\\n\\n\\nclass AuditPersistenceError(RuntimeError):\\n    \\\"\\\"\\\"A durable audit decision could not be committed to the database.\\n\\n    The message is deliberately fixed so database errors and credentials are\\n    never reflected into an API response. Operators can use the bounded\\n    producer-health failure code for diagnosis.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        super().__init__(\\\"Durable authorization audit persistence failed\\\")\\n\\n\\ndef _split_obj(obj: str) -> tuple[str | None, UUID | None]:\\n    \\\"\\\"\\\"Parse an authz obj key like 'flow:abc' into (resource_type, resource_id).\\n\\n    Wildcards (``flow:*``) and unparseable ids return None for ``resource_id``\\n    so audit rows are still written with the right ``resource_type``.\\n    \\\"\\\"\\\"\\n    if \\\":\\\" not in obj:\\n        return None, None\\n    resource_type, _, suffix = obj.partition(\\\":\\\")\\n    if not suffix or suffix == \\\"*\\\":\\n        return resource_type, None\\n    try:\\n        return resource_type, UUID(suffix)\\n    except (ValueError, TypeError):\\n        return resource_type, None\\n\\n\\ndef _coerce_uuid(value: Any) -> UUID | None:\\n    \\\"\\\"\\\"Return a UUID for trusted or string-like input without raising.\\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    if isinstance(value, UUID):\\n        return value\\n    try:\\n        return UUID(str(value))\\n    except (ValueError, TypeError, AttributeError):\\n        return None\\n\\n\\ndef _resolve_actor(\\n    user_id: UUID | None,\\n    principal: AuthorizationPrincipal | None = None,\\n) -> tuple[UUID | None, str, UUID | None]:\\n    \\\"\\\"\\\"Derive durable actor identity from the request credential and owner user.\\\"\\\"\\\"\\n    if principal is not None:\\n        return _coerce_uuid(principal.user_id), principal.actor_type, _coerce_uuid(principal.actor_id)\\n    resolved_user_id = _coerce_uuid(user_id)\\n    auth_context = get_current_auth_context()\\n    if resolved_user_id is not None and auth_context is not None and auth_context.method == AUTH_METHOD_API_KEY:\\n        return resolved_user_id, AUDIT_ACTOR_API_KEY, _coerce_uuid(auth_context.api_key_id)\\n    if resolved_user_id is not None:\\n        return resolved_user_id, AUDIT_ACTOR_USER, resolved_user_id\\n    return None, AUDIT_ACTOR_UNKNOWN, None\\n\\n\\ndef _merge_audit_details(\\n    details: dict[str, Any] | None,\\n    *,\\n    include_credential: bool,\\n) -> dict[str, Any] | None:\\n    \\\"\\\"\\\"Merge request credential metadata centrally while preserving caller details.\\\"\\\"\\\"\\n    credential_details = current_auth_context_for_audit() if include_credential else {}\\n    if details is None and not credential_details:\\n        return details\\n    merged = {**(details or {}), **credential_details}\\n    # These names are reserved for the first-class columns. Keeping caller\\n    # values in JSON as well would create a second, spoofable actor identity.\\n    merged.pop(\\\"actor_type\\\", None)\\n    merged.pop(\\\"actor_id\\\", None)\\n    return merged\\n\\n\\nclass _AuditEntry:\\n    \\\"\\\"\\\"One pending audit row.\\n\\n    A plain class (not a dataclass) so it can be instantiated cheaply from the\\n    request path without dataclass overhead. The fields mirror\\n    ``AuthzAuditLog`` columns plus the raw ``obj`` string \u2014 the writer splits\\n    ``obj`` into ``(resource_type, resource_id)`` once per batch.\\n    \\\"\\\"\\\"\\n\\n    __slots__ = (\\n        \\\"action\\\",\\n        \\\"actor_id\\\",\\n        \\\"actor_type\\\",\\n        \\\"details\\\",\\n        \\\"event_id\\\",\\n        \\\"obj\\\",\\n        \\\"occurred_at\\\",\\n        \\\"result\\\",\\n        \\\"user_id\\\",\\n    )\\n\\n    def __init__(\\n        self,\\n        *,\\n        user_id: UUID | None,\\n        actor_type: str,\\n        actor_id: UUID | None,\\n        action: str,\\n        obj: str,\\n        result: str,\\n        details: dict[str, Any] | None,\\n        event_id: UUID | None = None,\\n        occurred_at: datetime | None = None,\\n    ) -> None:\\n        self.user_id = user_id\\n        self.actor_type = actor_type\\n        self.actor_id = actor_id\\n        self.action = action\\n        self.obj = obj\\n        self.result = result\\n        self.details = details\\n        # Identity and event time are assigned before enqueue. This makes a\\n        # queued decision stable across batching delays and provides the seam\\n        # needed for idempotent downstream delivery.\\n        self.event_id = event_id or uuid4()\\n        self.occurred_at = occurred_at or datetime.now(timezone.utc)\\n\\n\\nclass _AuditEnvelope:\\n    \\\"\\\"\\\"Queue item with an optional durable commit acknowledgement.\\\"\\\"\\\"\\n\\n    __slots__ = (\\\"ack\\\", \\\"entry\\\", \\\"terminal\\\")\\n\\n    def __init__(self, entry: _AuditEntry, ack: asyncio.Future[None] | None = None) -> None:\\n        self.entry = entry\\n        self.ack = ack\\n        self.terminal = False\\n\\n\\n# Module-level state. Bound to whichever event loop is running when the first\\n# ``audit_decision`` call happens. ``_audit_queue_loop`` lets us detect a fresh\\n# loop (e.g. between pytest test cases) and restart the writer in the new loop\\n# instead of writing to a queue tied to a dead loop.\\n_audit_queue: asyncio.Queue[_AuditEnvelope] | None = None\\n_audit_queue_loop: asyncio.AbstractEventLoop | None = None\\n_audit_writer_task: asyncio.Task[None] | None = None\\n_audit_inflight: tuple[_AuditEnvelope, ...] = ()\\n_audit_accepting: bool = True\\n_audit_capacity_waiters: set[asyncio.Future[None]] = set()\\n_audit_dropped_count: int = 0\\n_audit_last_drop_warn: float = 0.0\\n_audit_submitted_count: int = 0\\n_audit_persisted_count: int = 0\\n_audit_failed_count: int = 0\\n_audit_last_failure_code: str | None = None\\n# Kept as a vestigial public name for backward compatibility with downstream\\n# callers (and the existing drain helper). The new pipeline tracks the single\\n# writer task here so ``drain_pending_audit_writes`` can await it.\\n_pending_audit_tasks: set[asyncio.Task[None]] = set()\\n\\n\\ndef _consume_ack_exception(future: asyncio.Future[None]) -> None:\\n    \\\"\\\"\\\"Retrieve a detached acknowledgement exception after caller cancellation.\\\"\\\"\\\"\\n    if not future.cancelled():\\n        future.exception()\\n\\n\\ndef _complete_persisted(batch: list[_AuditEnvelope]) -> None:\\n    \\\"\\\"\\\"Mark each previously accepted envelope durably committed exactly once.\\\"\\\"\\\"\\n    global _audit_persisted_count, _audit_last_failure_code  # noqa: PLW0603\\n\\n    for envelope in batch:\\n        if envelope.terminal:\\n            continue\\n        envelope.terminal = True\\n        _audit_persisted_count += 1\\n        if envelope.ack is not None and not envelope.ack.done():\\n            envelope.ack.set_result(None)\\n    _audit_last_failure_code = None\\n\\n\\ndef _complete_failed(batch: list[_AuditEnvelope] | tuple[_AuditEnvelope, ...], code: str) -> None:\\n    \\\"\\\"\\\"Give accepted envelopes a terminal, sanitized persistence failure.\\\"\\\"\\\"\\n    global _audit_failed_count, _audit_last_failure_code  # noqa: PLW0603\\n\\n    safe_code = code[:64]\\n    failed_any = False\\n    for envelope in batch:\\n        if envelope.terminal:\\n            continue\\n        envelope.terminal = True\\n        failed_any = True\\n        _audit_failed_count += 1\\n        if envelope.ack is not None and not envelope.ack.done():\\n            envelope.ack.set_exception(AuditPersistenceError())\\n    if failed_any:\\n        _audit_last_failure_code = safe_code\\n\\n\\ndef _release_capacity_waiters() -> None:\\n    \\\"\\\"\\\"Wake blocked durable producers after the writer frees queue capacity.\\\"\\\"\\\"\\n    for waiter in tuple(_audit_capacity_waiters):\\n        if not waiter.done():\\n            waiter.set_result(None)\\n\\n\\ndef _fail_capacity_waiters(code: str) -> None:\\n    \\\"\\\"\\\"Give every producer blocked before admission a sanitized terminal error.\\\"\\\"\\\"\\n    global _audit_last_failure_code  # noqa: PLW0603\\n\\n    failed_any = False\\n    for waiter in tuple(_audit_capacity_waiters):\\n        if not waiter.done():\\n            failed_any = True\\n            waiter.set_exception(AuditPersistenceError())\\n    if failed_any:\\n        _audit_last_failure_code = code[:64]\\n\\n\\ndef _discard_closed_loop_pipeline() -> None:\\n    \\\"\\\"\\\"Drop unreachable state after its owning event loop has closed.\\n\\n    Futures owned by a closed loop cannot be completed safely. No caller can\\n    still make progress on that loop, so account for accepted work as failed,\\n    discard references, and let the next live loop build a fresh pipeline.\\n    \\\"\\\"\\\"\\n    global _audit_accepting, _audit_failed_count, _audit_inflight  # noqa: PLW0603\\n    global _audit_last_failure_code, _audit_queue, _audit_queue_loop, _audit_writer_task  # noqa: PLW0603\\n\\n    abandoned = sum(not envelope.terminal for envelope in _audit_inflight)\\n    if _audit_queue is not None:\\n        abandoned += _audit_queue.qsize()\\n    if abandoned:\\n        _audit_failed_count += abandoned\\n        _audit_last_failure_code = \\\"loop_replaced\\\"\\n    _audit_queue = None\\n    _audit_queue_loop = None\\n    _audit_writer_task = None\\n    _audit_inflight = ()\\n    _audit_accepting = False\\n    _audit_capacity_waiters.clear()\\n    _pending_audit_tasks.clear()\\n\\n\\ndef _fail_queued_entries(queue: asyncio.Queue[_AuditEnvelope], code: str) -> None:\\n    \\\"\\\"\\\"Remove and terminally fail all entries left behind by a stopped writer.\\\"\\\"\\\"\\n    while True:\\n        try:\\n            envelope = queue.get_nowait()\\n        except asyncio.QueueEmpty:\\n            return\\n        _complete_failed([envelope], code)\\n        queue.task_done()\\n\\n\\ndef _audit_writer_finished(task: asyncio.Task[None]) -> None:\\n    \\\"\\\"\\\"Fail accepted work if the writer exits outside the controlled shutdown path.\\\"\\\"\\\"\\n    _pending_audit_tasks.discard(task)\\n    if task is not _audit_writer_task or not _audit_accepting:\\n        return\\n\\n    code = \\\"writer_stopped\\\"\\n    if not task.cancelled():\\n        error = task.exception()\\n        if error is not None:\\n            code = type(error).__name__\\n    _complete_failed(_audit_inflight, code)\\n    if _audit_queue is not None:\\n        _fail_queued_entries(_audit_queue, code)\\n    _fail_capacity_waiters(code)\\n\\n\\nasync def _admit_durable(queue: asyncio.Queue[_AuditEnvelope], envelope: _AuditEnvelope) -> None:\\n    \\\"\\\"\\\"Atomically admit one durable entry or reject it when shutdown closes admission.\\\"\\\"\\\"\\n    global _audit_last_failure_code, _audit_submitted_count  # noqa: PLW0603\\n\\n    loop = asyncio.get_running_loop()\\n    while True:\\n        writer = _audit_writer_task\\n        if not _audit_accepting or writer is None or writer.done():\\n            _audit_last_failure_code = \\\"writer_stopped\\\"\\n            raise AuditPersistenceError\\n        try:\\n            # There is no await between the admission check and put_nowait, so\\n            # shutdown cannot interleave on this event loop and sweep too soon.\\n            queue.put_nowait(envelope)\\n        except asyncio.QueueFull:\\n            waiter: asyncio.Future[None] = loop.create_future()\\n            waiter.add_done_callback(_consume_ack_exception)\\n            _audit_capacity_waiters.add(waiter)\\n            try:\\n                await waiter\\n            finally:\\n                _audit_capacity_waiters.discard(waiter)\\n            continue\\n        _audit_submitted_count += 1\\n        return\\n\\n\\ndef _ensure_audit_writer_started() -> asyncio.Queue[_AuditEnvelope] | None:\\n    \\\"\\\"\\\"Lazily start the audit writer task in the current event loop.\\n\\n    Returns the queue, or ``None`` if no event loop is running (audit is\\n    skipped entirely in that case \u2014 there's no place to schedule the writer).\\n    \\\"\\\"\\\"\\n    global _audit_accepting, _audit_inflight, _audit_queue, _audit_queue_loop, _audit_writer_task  # noqa: PLW0603\\n\\n    try:\\n        loop = asyncio.get_running_loop()\\n    except RuntimeError:\\n        return None\\n\\n    if _audit_queue_loop is not None and _audit_queue_loop is not loop:\\n        if not _audit_queue_loop.is_closed():\\n            # The module-level producer is intentionally single-loop. Refuse a\\n            # concurrent second loop without mutating the live owner's state.\\n            global _audit_last_failure_code  # noqa: PLW0603\\n\\n            _audit_last_failure_code = \\\"loop_mismatch\\\"\\n            return None\\n        _discard_closed_loop_pipeline()\\n\\n    # A fresh event loop replaces the previous queue+writer. Without this,\\n    # a subsequent ``audit_decision`` call (e.g. in a new pytest test) would\\n    # ``put_nowait`` into a queue that no live task is consuming.\\n    if _audit_queue_loop is not loop:\\n        _audit_queue = asyncio.Queue(maxsize=_AUDIT_QUEUE_MAX)\\n        _audit_queue_loop = loop\\n        _audit_writer_task = None\\n        _audit_inflight = ()\\n        _audit_accepting = True\\n        _audit_capacity_waiters.clear()\\n        _pending_audit_tasks.clear()\\n\\n    if _audit_writer_task is None or _audit_writer_task.done():\\n        _audit_writer_task = loop.create_task(_audit_writer_loop())\\n        _pending_audit_tasks.add(_audit_writer_task)\\n        _audit_writer_task.add_done_callback(_audit_writer_finished)\\n\\n    return _audit_queue\\n\\n\\nasync def _audit_writer_loop() -> None:\\n    \\\"\\\"\\\"Drain the audit queue and write batches to the DB.\\n\\n    Loops until cancelled. Each iteration blocks on the first row, then greedily\\n    pulls everything else already enqueued up to ``_AUDIT_BATCH_MAX`` and\\n    commits them as a single batch insert. In best-effort mode DB exceptions\\n    remain asynchronous; in durable mode the affected callers receive a fixed,\\n    sanitized ``AuditPersistenceError``.\\n    \\\"\\\"\\\"\\n    global _audit_inflight  # noqa: PLW0603\\n\\n    while True:\\n        queue = _audit_queue\\n        if queue is None:\\n            return\\n        try:\\n            first = await queue.get()\\n        except asyncio.CancelledError:\\n            return\\n\\n        batch: list[_AuditEnvelope] = [first]\\n        try:\\n            while len(batch) < _AUDIT_BATCH_MAX:\\n                batch.append(queue.get_nowait())\\n        except asyncio.QueueEmpty:\\n            pass\\n        _release_capacity_waiters()\\n\\n        try:\\n            _audit_inflight = tuple(batch)\\n            await _flush_audit_batch([envelope.entry for envelope in batch])\\n        except asyncio.CancelledError:\\n            _complete_failed(batch, \\\"writer_stopped\\\")\\n            return\\n        except Exception as exc:  # noqa: BLE001 \u2014 never let the writer die quietly\\n            # Never log the exception value: database URLs and driver errors\\n            # can contain credentials. The class name is enough for a bounded\\n            # operator signal and is safe to expose through producer health.\\n            failure_code = type(exc).__name__\\n            logger.error(\\n                \\\"Authz audit writer batch flush failed for %d row(s) (%s)\\\",\\n                len(batch),\\n                failure_code,\\n            )\\n            _complete_failed(batch, failure_code)\\n        except BaseException as exc:\\n            # System-level task termination is re-raised after accepted work\\n            # receives a terminal failure. The done callback then fails work\\n            # that was still queued behind this batch.\\n            _complete_failed(batch, type(exc).__name__)\\n            raise\\n        else:\\n            _complete_persisted(batch)\\n        finally:\\n            for _ in batch:\\n                queue.task_done()\\n            _audit_inflight = ()\\n\\n\\nasync def _flush_audit_batch(batch: list[_AuditEntry]) -> None:\\n    \\\"\\\"\\\"Insert a batch of ``_AuditEntry`` rows in a single session.\\\"\\\"\\\"\\n    if not batch:\\n        return\\n    from langflow.services.deps import session_scope\\n\\n    async with session_scope() as session:\\n        _stage_audit_entries(session, batch)\\n\\n\\ndef _stage_audit_entries(session: AsyncSession, entries: list[_AuditEntry]) -> None:\\n    \\\"\\\"\\\"Add audit rows and plugin events to an existing transaction.\\\"\\\"\\\"\\n    # Imported lazily so callers with auditing disabled do not pull DB models.\\n    from lfx.services.authorization import AuthorizationAuditEvent\\n\\n    from langflow.services.database.models.auth import AuthzAuditLog\\n    from langflow.services.deps import get_authorization_service\\n\\n    events: list[AuthorizationAuditEvent] = []\\n    for entry in entries:\\n        resource_type, resource_id = _split_obj(entry.obj)\\n        session.add(\\n            AuthzAuditLog(\\n                id=entry.event_id,\\n                timestamp=entry.occurred_at,\\n                user_id=entry.user_id,\\n                actor_type=entry.actor_type,\\n                actor_id=entry.actor_id,\\n                action=entry.action,\\n                resource_type=resource_type,\\n                resource_id=resource_id,\\n                result=entry.result,\\n                details=entry.details,\\n            )\\n        )\\n        events.append(\\n            AuthorizationAuditEvent(\\n                event_id=entry.event_id,\\n                occurred_at=entry.occurred_at,\\n            )\\n        )\\n    get_authorization_service().stage_audit_events(session=session, events=tuple(events))\\n\\n\\ndef stage_audit_decision(\\n    *,\\n    session: AsyncSession,\\n    user_id: UUID | None,\\n    principal: AuthorizationPrincipal | None = None,\\n    action: str,\\n    obj: str,\\n    result: str,\\n    details: dict[str, Any] | None = None,\\n) -> bool:\\n    \\\"\\\"\\\"Stage a durable audit row in a caller-owned mutation transaction.\\n\\n    Returns ``True`` when the row was staged. Best-effort mode returns ``False``\\n    so the caller can submit through the asynchronous audit pipeline after its\\n    mutation commits.\\n    \\\"\\\"\\\"\\n    auth_settings = get_settings_service().auth_settings\\n    if not getattr(auth_settings, \\\"AUTHZ_AUDIT_ENABLED\\\", False) or not getattr(\\n        auth_settings, \\\"AUTHZ_AUDIT_DURABLE\\\", False\\n    ):\\n        return False\\n\\n    resolved_user_id, actor_type, actor_id = _resolve_actor(user_id, principal)\\n    entry = _AuditEntry(\\n        user_id=resolved_user_id,\\n        actor_type=actor_type,\\n        actor_id=actor_id,\\n        action=action,\\n        obj=obj,\\n        result=result,\\n        details=_merge_audit_details(details, include_credential=resolved_user_id is not None),\\n    )\\n    _stage_audit_entries(session, [entry])\\n    return True\\n\\n\\nasync def drain_pending_audit_writes(timeout: float = 5.0) -> None:\\n    \\\"\\\"\\\"Flush the audit queue and stop the writer (bounded by ``timeout``).\\n\\n    Safe to call multiple times; safe to call when no audit traffic has run.\\n    Splits the timeout between draining the queue and awaiting writer\\n    cancellation so neither side can hang shutdown indefinitely.\\n    \\\"\\\"\\\"\\n    global _audit_accepting, _audit_queue_loop, _audit_writer_task  # noqa: PLW0603\\n\\n    try:\\n        loop = asyncio.get_running_loop()\\n    except RuntimeError:\\n        loop = None\\n    if _audit_queue_loop is not None and _audit_queue_loop is not loop:\\n        if _audit_queue_loop.is_closed():\\n            _discard_closed_loop_pipeline()\\n        else:\\n            global _audit_last_failure_code  # noqa: PLW0603\\n\\n            _audit_last_failure_code = \\\"loop_mismatch\\\"\\n        return\\n\\n    _audit_accepting = False\\n    _fail_capacity_waiters(\\\"writer_stopped\\\")\\n\\n    queue = _audit_queue\\n    writer = _audit_writer_task\\n    if queue is None:\\n        # Closing admission must be owned by this loop even when lazy startup\\n        # never created a queue. The same-loop durable guard can then keep the\\n        # idle pipeline terminal while a later, genuinely new loop replaces it.\\n        _audit_queue_loop = loop\\n        return\\n    if writer is None:\\n        _fail_queued_entries(queue, \\\"writer_stopped\\\")\\n        return\\n\\n    drain_budget = max(0.1, timeout * 0.8)\\n    cancel_budget = max(0.1, timeout - drain_budget)\\n\\n    try:\\n        await asyncio.wait_for(queue.join(), timeout=drain_budget)\\n    except asyncio.TimeoutError:\\n        logger.warning(\\n            \\\"drain_pending_audit_writes timed out after %.2fs with %d row(s) pending\\\",\\n            drain_budget,\\n            queue.qsize(),\\n        )\\n\\n    if not writer.done():\\n        writer.cancel()\\n        from contextlib import suppress\\n\\n        with suppress(asyncio.CancelledError, asyncio.TimeoutError):\\n            await asyncio.wait_for(writer, timeout=cancel_budget)\\n\\n    _complete_failed(_audit_inflight, \\\"writer_stopped\\\")\\n    _fail_queued_entries(queue, \\\"writer_stopped\\\")\\n    _fail_capacity_waiters(\\\"writer_stopped\\\")\\n\\n    _pending_audit_tasks.discard(writer)\\n    _audit_writer_task = None\\n\\n\\nasync def audit_decision(\\n    *,\\n    user_id: UUID | None,\\n    principal: AuthorizationPrincipal | None = None,\\n    action: str,\\n    obj: str,\\n    result: str,\\n    details: dict[str, Any] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Submit an AuthzAuditLog row to the batched database writer.\\n\\n    Legacy mode is best effort and non-blocking: saturation drops the row with\\n    a time-bounded warning. With ``AUTHZ_AUDIT_DURABLE=True``, bounded queue\\n    capacity backpressures the caller and return means the database batch has\\n    committed. Audit is fully bypassed when ``AUTHZ_AUDIT_ENABLED=False``.\\n    \\\"\\\"\\\"\\n    global _audit_dropped_count, _audit_last_drop_warn, _audit_last_failure_code, _audit_submitted_count  # noqa: PLW0603\\n\\n    settings = get_settings_service()\\n    auth_settings = settings.auth_settings\\n    # Audit is independent of enforcement. ``AuthSettings.AUTHZ_AUDIT_ENABLED``\\n    # defaults to ``False`` (see lfx/services/settings/auth.py) because the\\n    # background writer still consumes a DB connection; operators opt in.\\n    if not getattr(auth_settings, \\\"AUTHZ_AUDIT_ENABLED\\\", False):\\n        return\\n\\n    durable = bool(getattr(auth_settings, \\\"AUTHZ_AUDIT_DURABLE\\\", False))\\n    # A completed same-loop drain is terminal. Reject before the lazy starter\\n    # can create an idle replacement writer; a genuinely new event loop still\\n    # flows through ``_ensure_audit_writer_started`` and replaces the closed\\n    # loop's pipeline below.\\n    if durable and _audit_queue_loop is asyncio.get_running_loop() and not _audit_accepting:\\n        _audit_last_failure_code = \\\"writer_stopped\\\"\\n        raise AuditPersistenceError\\n    queue = _ensure_audit_writer_started()\\n    if queue is None:\\n        if durable:\\n            _audit_last_failure_code = \\\"writer_unavailable\\\"\\n            raise AuditPersistenceError\\n        return\\n    if durable and not _audit_accepting:\\n        _audit_last_failure_code = \\\"writer_stopped\\\"\\n        raise AuditPersistenceError\\n\\n    resolved_user_id, actor_type, actor_id = _resolve_actor(user_id, principal)\\n    entry = _AuditEntry(\\n        user_id=resolved_user_id,\\n        actor_type=actor_type,\\n        actor_id=actor_id,\\n        action=action,\\n        obj=obj,\\n        result=result,\\n        details=_merge_audit_details(details, include_credential=resolved_user_id is not None),\\n    )\\n    if durable:\\n        loop = asyncio.get_running_loop()\\n        ack: asyncio.Future[None] = loop.create_future()\\n        # A timed-out request no longer awaits this future, so consume any\\n        # eventual failure to avoid an unhandled-future warning. ``shield``\\n        # below ensures cancellation does not cancel the persistence itself.\\n        ack.add_done_callback(_consume_ack_exception)\\n        await _admit_durable(queue, _AuditEnvelope(entry, ack))\\n        await asyncio.shield(ack)\\n        return\\n\\n    try:\\n        queue.put_nowait(_AuditEnvelope(entry))\\n        _audit_submitted_count += 1\\n    except asyncio.QueueFull:\\n        _audit_dropped_count += 1\\n        _audit_last_failure_code = \\\"queue_full\\\"\\n        # Time-based: always log the first drop, then at most once per\\n        # ``_AUDIT_DROP_WARN_INTERVAL`` while saturation persists. Cheaper to\\n        # reason about for operators than the previous every-1000th heuristic\\n        # (which could go minutes without a log line at low drop rates).\\n        now = time.monotonic()\\n        if _audit_dropped_count == 1 or (now - _audit_last_drop_warn) >= _AUDIT_DROP_WARN_INTERVAL:\\n            _audit_last_drop_warn = now\\n            logger.warning(\\n                \\\"AuthzAuditLog queue full (%d/%d); dropped %d row(s) total. DB writer is likely behind or stalled.\\\",\\n                queue.qsize(),\\n                _AUDIT_QUEUE_MAX,\\n                _audit_dropped_count,\\n            )\\n\\n\\ndef get_audit_producer_health() -> dict[str, bool | int | str | None]:\\n    \\\"\\\"\\\"Return a bounded, credential-free snapshot of the local audit producer.\\\"\\\"\\\"\\n    auth_settings = get_settings_service().auth_settings\\n    queue = _audit_queue\\n    writer = _audit_writer_task\\n    return {\\n        \\\"enabled\\\": bool(getattr(auth_settings, \\\"AUTHZ_AUDIT_ENABLED\\\", False)),\\n        \\\"durable\\\": bool(getattr(auth_settings, \\\"AUTHZ_AUDIT_DURABLE\\\", False)),\\n        \\\"active\\\": writer is not None and not writer.done(),\\n        \\\"healthy\\\": _audit_last_failure_code is None,\\n        \\\"queue_depth\\\": queue.qsize() if queue is not None else 0,\\n        \\\"queue_capacity\\\": _AUDIT_QUEUE_MAX,\\n        \\\"submitted_count\\\": _audit_submitted_count,\\n        \\\"persisted_count\\\": _audit_persisted_count,\\n        \\\"failed_count\\\": _audit_failed_count,\\n        \\\"dropped_count\\\": _audit_dropped_count,\\n        \\\"last_failure_code\\\": _audit_last_failure_code,\\n    }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/decorators.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1ba4abe9675bc11c1a87aef51411d7f35156cbd5a15a29c1fbb9a9da272fe881\",\"content\":\"\\\"\\\"\\\"Declarative permission enforcement for non-route async call paths.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport functools\\nimport inspect\\nfrom collections.abc import Awaitable, Callable\\nfrom typing import TYPE_CHECKING, Any, TypeVar\\n\\nfrom fastapi import HTTPException, status\\n\\nfrom langflow.services.authorization.actions import (\\n    DeploymentAction,\\n    FileAction,\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ProjectAction,\\n    ShareAction,\\n    VariableAction,\\n)\\nfrom langflow.services.authorization.guards import (\\n    _RESOURCE_SPECS,\\n    ensure_deployment_permission,\\n    ensure_file_permission,\\n    ensure_flow_permission,\\n    ensure_knowledge_base_permission,\\n    ensure_project_permission,\\n    ensure_share_permission,\\n    ensure_variable_permission,\\n)\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.user.model import User, UserRead\\n\\n_Action = (\\n    DeploymentAction\\n    | FlowAction\\n    | ProjectAction\\n    | KnowledgeBaseAction\\n    | VariableAction\\n    | FileAction\\n    | ShareAction\\n    | str\\n)\\n\\n_ENSURE_BY_SPEC: dict[str, Callable[..., Awaitable[None]]] = {\\n    \\\"flow\\\": ensure_flow_permission,\\n    \\\"deployment\\\": ensure_deployment_permission,\\n    \\\"project\\\": ensure_project_permission,\\n    \\\"knowledge_base\\\": ensure_knowledge_base_permission,\\n    \\\"variable\\\": ensure_variable_permission,\\n    \\\"file\\\": ensure_file_permission,\\n    \\\"share\\\": ensure_share_permission,\\n}\\n\\n# Map registry specs to ORM attribute names used when ``resource_param`` is set.\\n_ORM_ATTR_BY_SPEC_KW: dict[str, dict[str, str]] = {\\n    \\\"flow\\\": {\\n        \\\"flow_id\\\": \\\"id\\\",\\n        \\\"flow_user_id\\\": \\\"user_id\\\",\\n        \\\"workspace_id\\\": \\\"workspace_id\\\",\\n        \\\"folder_id\\\": \\\"folder_id\\\",\\n    },\\n    \\\"deployment\\\": {\\n        \\\"deployment_id\\\": \\\"id\\\",\\n        \\\"deployment_user_id\\\": \\\"user_id\\\",\\n        \\\"workspace_id\\\": \\\"workspace_id\\\",\\n        \\\"project_id\\\": \\\"project_id\\\",\\n    },\\n    \\\"project\\\": {\\n        \\\"project_id\\\": \\\"id\\\",\\n        \\\"project_user_id\\\": \\\"user_id\\\",\\n        \\\"workspace_id\\\": \\\"workspace_id\\\",\\n    },\\n    \\\"knowledge_base\\\": {\\n        \\\"kb_id\\\": \\\"id\\\",\\n        \\\"kb_user_id\\\": \\\"user_id\\\",\\n        \\\"workspace_id\\\": \\\"workspace_id\\\",\\n        \\\"project_id\\\": \\\"project_id\\\",\\n        \\\"kb_name\\\": \\\"name\\\",\\n    },\\n    \\\"variable\\\": {\\n        \\\"variable_id\\\": \\\"id\\\",\\n        \\\"variable_user_id\\\": \\\"user_id\\\",\\n        \\\"workspace_id\\\": \\\"workspace_id\\\",\\n    },\\n    \\\"file\\\": {\\n        \\\"file_id\\\": \\\"id\\\",\\n        \\\"file_user_id\\\": \\\"user_id\\\",\\n        \\\"workspace_id\\\": \\\"workspace_id\\\",\\n    },\\n    \\\"share\\\": {\\n        \\\"share_id\\\": \\\"id\\\",\\n        \\\"share_user_id\\\": \\\"user_id\\\",\\n    },\\n}\\n\\n_F = TypeVar(\\\"_F\\\", bound=Callable[..., Awaitable[Any]])\\n\\n\\ndef _action_value(act: _Action) -> str:\\n    \\\"\\\"\\\"Return the string value for enum-like and raw-string actions.\\\"\\\"\\\"\\n    return str(getattr(act, \\\"value\\\", act))\\n\\n\\ndef _requires_resource_id(act: _Action) -> bool:\\n    \\\"\\\"\\\"Return True when the action targets an existing resource.\\\"\\\"\\\"\\n    return _action_value(act) != \\\"create\\\"\\n\\n\\ndef _raise_missing_resource_id(func_name: str, spec_key: str, id_kw: str) -> None:\\n    msg = f\\\"@requires_resource_permission: '{func_name}' requires a non-null '{id_kw}' for {spec_key} permission\\\"\\n    raise ValueError(msg)\\n\\n\\ndef _kwargs_from_resource(spec_key: str, resource: Any) -> dict[str, Any]:\\n    \\\"\\\"\\\"Build ensure_* kwargs from a loaded ORM row.\\\"\\\"\\\"\\n    spec = _RESOURCE_SPECS[spec_key]\\n    attr_map = _ORM_ATTR_BY_SPEC_KW[spec_key]\\n    out: dict[str, Any] = {}\\n    if spec.id_kw in attr_map:\\n        out[spec.id_kw] = getattr(resource, attr_map[spec.id_kw], None)\\n    if spec.owner_kw in attr_map:\\n        out[spec.owner_kw] = getattr(resource, attr_map[spec.owner_kw], None)\\n    if spec.workspace_kw and spec.workspace_kw in attr_map:\\n        out[spec.workspace_kw] = getattr(resource, attr_map[spec.workspace_kw], None)\\n    if spec.scope_kw and spec.scope_kw in attr_map:\\n        out[spec.scope_kw] = getattr(resource, attr_map[spec.scope_kw], None)\\n    for extra in spec.extra_context_kws:\\n        if extra in attr_map:\\n            out[extra] = getattr(resource, attr_map[extra], None)\\n    return out\\n\\n\\ndef requires_resource_permission(\\n    spec_key: str,\\n    act: _Action,\\n    *,\\n    user_param: str = \\\"user\\\",\\n    resource_param: str | None = None,\\n    forbidden_as_not_found: bool = False,\\n    not_found_template: str = \\\"Resource not found\\\",\\n) -> Callable[[_F], _F]:\\n    \\\"\\\"\\\"Enforce a resource permission before the decorated async function runs.\\n\\n    When ``resource_param`` is set, permission kwargs are taken from that ORM\\n    object (e.g. a loaded ``Flow``). Otherwise the decorated function must\\n    expose parameters matching the registry's public kwarg names\\n    (``flow_id``, ``flow_user_id``, ...).\\n\\n    ``forbidden_as_not_found`` maps HTTP 403 to ``ValueError`` for helpers\\n    that historically surfaced denials as \\\"not found\\\" (e.g. ``load_flow``).\\n    \\\"\\\"\\\"\\n    if spec_key not in _RESOURCE_SPECS:\\n        msg = f\\\"Unknown resource spec: {spec_key}\\\"\\n        raise ValueError(msg)\\n\\n    ensure_fn = _ENSURE_BY_SPEC[spec_key]\\n\\n    def decorator(func: _F) -> _F:\\n        sig = inspect.signature(func)\\n\\n        if user_param not in sig.parameters:\\n            msg = (\\n                f\\\"@requires_resource_permission: '{func.__name__}' must have \\\"\\n                f\\\"a '{user_param}' parameter (got {list(sig.parameters)})\\\"\\n            )\\n            raise TypeError(msg)\\n        if resource_param is not None and resource_param not in sig.parameters:\\n            msg = (\\n                f\\\"@requires_resource_permission: '{func.__name__}' must have \\\"\\n                f\\\"a '{resource_param}' parameter when resource_param is set\\\"\\n            )\\n            raise TypeError(msg)\\n        spec = _RESOURCE_SPECS[spec_key]\\n        if resource_param is None and _requires_resource_id(act) and spec.id_kw not in sig.parameters:\\n            msg = (\\n                f\\\"@requires_resource_permission: '{func.__name__}' must have \\\"\\n                f\\\"a '{spec.id_kw}' parameter for {spec_key} permission\\\"\\n            )\\n            raise TypeError(msg)\\n\\n        @functools.wraps(func)\\n        async def wrapper(*args: Any, **kwargs: Any) -> Any:\\n            bound = sig.bind(*args, **kwargs)\\n            bound.apply_defaults()\\n            arguments = bound.arguments\\n\\n            user: User | UserRead = arguments[user_param]\\n            if resource_param is not None:\\n                perm_kwargs = _kwargs_from_resource(spec_key, arguments[resource_param])\\n            else:\\n                perm_kwargs = {}\\n                for kw in (\\n                    spec.id_kw,\\n                    spec.owner_kw,\\n                    *(spec.extra_context_kws or ()),\\n                ):\\n                    if kw in arguments:\\n                        perm_kwargs[kw] = arguments[kw]\\n                if spec.workspace_kw and spec.workspace_kw in arguments:\\n                    perm_kwargs[spec.workspace_kw] = arguments[spec.workspace_kw]\\n                if spec.scope_kw and spec.scope_kw in arguments:\\n                    perm_kwargs[spec.scope_kw] = arguments[spec.scope_kw]\\n\\n            if _requires_resource_id(act) and perm_kwargs.get(spec.id_kw) is None:\\n                _raise_missing_resource_id(func.__name__, spec_key, spec.id_kw)\\n\\n            try:\\n                await ensure_fn(user, act, **perm_kwargs)\\n            except HTTPException as exc:\\n                if forbidden_as_not_found and exc.status_code == status.HTTP_403_FORBIDDEN:\\n                    raise ValueError(not_found_template) from exc\\n                raise\\n            return await func(*args, **kwargs)\\n\\n        return wrapper  # type: ignore[return-value]\\n\\n    return decorator\\n\\n\\ndef requires_flow_permission(\\n    act: FlowAction | str,\\n    *,\\n    user_param: str = \\\"user\\\",\\n    flow_id_param: str = \\\"flow_id\\\",\\n    flow_user_id_param: str = \\\"flow_user_id\\\",\\n    flow_param: str | None = None,\\n    forbidden_as_not_found: bool = False,\\n    not_found_template: str = \\\"Flow not found\\\",\\n) -> Callable[[_F], _F]:\\n    \\\"\\\"\\\"Flow-specific wrapper over :func:`requires_resource_permission`.\\\"\\\"\\\"\\n    if flow_param is not None:\\n        return requires_resource_permission(\\n            \\\"flow\\\",\\n            act,\\n            user_param=user_param,\\n            resource_param=flow_param,\\n            forbidden_as_not_found=forbidden_as_not_found,\\n            not_found_template=not_found_template,\\n        )\\n\\n    def decorator(func: _F) -> _F:\\n        sig = inspect.signature(func)\\n        if user_param not in sig.parameters:\\n            msg = (\\n                f\\\"@requires_flow_permission: '{func.__name__}' must have \\\"\\n                f\\\"a '{user_param}' parameter (got {list(sig.parameters)})\\\"\\n            )\\n            raise TypeError(msg)\\n        if _requires_resource_id(act) and flow_id_param not in sig.parameters:\\n            msg = (\\n                f\\\"@requires_flow_permission: '{func.__name__}' must have \\\"\\n                f\\\"a '{flow_id_param}' parameter for flow permission\\\"\\n            )\\n            raise TypeError(msg)\\n\\n        @functools.wraps(func)\\n        async def wrapper(*args: Any, **kwargs: Any) -> Any:\\n            bound = sig.bind(*args, **kwargs)\\n            bound.apply_defaults()\\n            arguments = bound.arguments\\n            perm_kwargs = {\\n                \\\"flow_id\\\": arguments.get(flow_id_param),\\n                \\\"flow_user_id\\\": arguments.get(flow_user_id_param),\\n                \\\"workspace_id\\\": arguments.get(\\\"workspace_id\\\"),\\n                \\\"folder_id\\\": arguments.get(\\\"folder_id\\\"),\\n            }\\n            if _requires_resource_id(act) and perm_kwargs[\\\"flow_id\\\"] is None:\\n                _raise_missing_resource_id(func.__name__, \\\"flow\\\", \\\"flow_id\\\")\\n            try:\\n                await ensure_flow_permission(arguments[user_param], act, **perm_kwargs)\\n            except HTTPException as exc:\\n                if forbidden_as_not_found and exc.status_code == status.HTTP_403_FORBIDDEN:\\n                    raise ValueError(not_found_template) from exc\\n                raise\\n            return await func(*args, **kwargs)\\n\\n        return wrapper  # type: ignore[return-value]\\n\\n    return decorator\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4db5911c02ec0512c87a2d49d4a0aae3ba5eedbd96368282964a39f76365e3ad\",\"content\":\"\\\"\\\"\\\"Authorization service factory.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.schema import ServiceType\\n\\nif TYPE_CHECKING:\\n    from lfx.services.authorization.base import BaseAuthorizationService\\n    from lfx.services.settings.service import SettingsService\\n\\n    from langflow.services.authorization.service import LangflowAuthorizationService\\n\\n\\nclass AuthorizationServiceFactory(ServiceFactory):\\n    \\\"\\\"\\\"Factory that creates the Langflow authorization service.\\\"\\\"\\\"\\n\\n    name = ServiceType.AUTHORIZATION_SERVICE.value\\n\\n    service_class: type[LangflowAuthorizationService]\\n\\n    def __init__(self) -> None:\\n        \\\"\\\"\\\"Bind the factory to the LangflowAuthorizationService implementation.\\\"\\\"\\\"\\n        from langflow.services.authorization.service import LangflowAuthorizationService\\n\\n        super().__init__(LangflowAuthorizationService)\\n\\n    def create(self, settings_service: SettingsService) -> BaseAuthorizationService:\\n        \\\"\\\"\\\"Build a LangflowAuthorizationService using the injected settings service.\\\"\\\"\\\"\\n        return self.service_class(settings_service)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/fetch.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7865015f0c086b905f3560118b38feff8951f4723a2b360599524f85f34ce5f4\",\"content\":\"\\\"\\\"\\\"Share-aware fetch helpers for authorization-guarded routes.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, TypeVar\\n\\nfrom fastapi import HTTPException, status\\nfrom sqlmodel import select\\n\\nfrom langflow.services.deps import get_authorization_service\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Awaitable, Callable\\n    from uuid import UUID\\n\\n    from sqlalchemy.orm.attributes import InstrumentedAttribute\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\nT = TypeVar(\\\"T\\\")\\n\\n\\nasync def authorized_or_owner_scoped(\\n    session: AsyncSession,\\n    model: type[T],\\n    *,\\n    id_column: InstrumentedAttribute,\\n    resource_id: UUID,\\n    owner_column: InstrumentedAttribute,\\n    owner_id: UUID,\\n    for_update: bool = False,\\n) -> T | None:\\n    \\\"\\\"\\\"Load by id when cross-user fetch is supported; otherwise scope by owner.\\n\\n    ``for_update`` refreshes any identity-map instance from the database and\\n    locks the selected row through the caller's transaction. Write paths use\\n    this to keep authorization of the current scope atomic with the mutation.\\n    \\\"\\\"\\\"\\n    authz = get_authorization_service()\\n    # Require both plugin capability and AUTHZ_ENABLED before widening the query.\\n    if await authz.supports_cross_user_fetch() and await authz.is_enabled():\\n        stmt = select(model).where(id_column == resource_id)\\n    else:\\n        stmt = select(model).where(id_column == resource_id).where(owner_column == owner_id)\\n    if for_update:\\n        stmt = stmt.with_for_update().execution_options(populate_existing=True)\\n    return (await session.exec(stmt)).first()\\n\\n\\ndef deny_to_404(exc: HTTPException, detail: str = \\\"Not found\\\") -> HTTPException:\\n    \\\"\\\"\\\"Map a 403 permission-deny to 404 (UUID privacy); return any other error unchanged.\\\"\\\"\\\"\\n    if exc.status_code == status.HTTP_403_FORBIDDEN:\\n        return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=detail)\\n    # Never relabel a non-403 (e.g. 4xx/5xx) as \\\"not found\\\"; surface it unchanged.\\n    return exc\\n\\n\\nasync def deny_to_404_unless_readable(\\n    exc: HTTPException,\\n    read_check: Callable[[], Awaitable[None]],\\n    *,\\n    denied_detail: str,\\n    not_found_detail: str = \\\"Not found\\\",\\n) -> HTTPException:\\n    \\\"\\\"\\\"Answer a denied action honestly when the caller can already read the resource.\\n\\n    The 404 mask exists so a caller cannot probe UUIDs they have no access to.\\n    It buys nothing once the caller has read the resource \u2014 they already know it\\n    exists \u2014 and it costs them a truthful answer: \\\"not found\\\" sends someone to\\n    debug an identifier that is correct, when the real answer is that they lack\\n    a permission. So: readable -> 403 with ``denied_detail``, unreadable ->\\n    404 with ``not_found_detail``.\\n\\n    ``read_check`` must raise ``HTTPException`` when the caller may not read.\\n    Only a 403 means \\\"cannot see it\\\"; any other status from either the original\\n    denial or the read check is a different answer entirely -- a 503 from the\\n    authorization plugin says the decision is unavailable, not that the resource\\n    is missing -- and is surfaced unchanged rather than relabelled.\\n    \\\"\\\"\\\"\\n    if exc.status_code != status.HTTP_403_FORBIDDEN:\\n        return exc\\n    try:\\n        await read_check()\\n    except HTTPException as read_exc:\\n        if read_exc.status_code != status.HTTP_403_FORBIDDEN:\\n            # Reporting a service failure as \\\"not found\\\" hides an outage behind\\n            # a routine-looking response and sends the caller to check their id.\\n            return read_exc\\n        return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=not_found_detail)\\n    return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=denied_detail)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/authorization/flow_data_override.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7bc497acc80a55620a86010515eed6732b73024772901838ad363fed2de10492\",\"content\":\"\\\"\\\"\\\"Whether a caller's run-time graph override may be honored.\\n\\n``POST /api/v2/workflows`` and ``POST /api/v1/build/{id}/flow`` both accept\\ncaller-supplied graph data so the canvas can run edits that are not saved yet.\\nSubstituting a graph and running it under the owner's resources is an edit, so\\nit is gated on ``flow:write`` rather than on ownership: a caller who holds write\\ncan already persist that graph and run it, so honoring the unsaved copy grants\\nnothing new, while an execute-only caller still cannot choose what runs.\\n\\nThe verdict is resolved once per request in an async authorization step and\\nread by the synchronous request gates, which run in all three execution modes.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextvars import ContextVar\\nfrom typing import TYPE_CHECKING\\n\\nfrom fastapi import HTTPException\\n\\nfrom langflow.api.utils.execution_errors import caller_owns_flow\\nfrom langflow.services.authorization.actions import FlowAction\\nfrom langflow.services.authorization.guards import ensure_flow_permission\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.flow.model import FlowRead\\n    from langflow.services.database.models.user.model import UserRead\\n\\n# Default False so an unresolved request falls back to owner-only overrides,\\n# which is the behavior every caller had before the verdict existed.\\n_flow_data_override_allowed: ContextVar[bool] = ContextVar(\\n    \\\"langflow_flow_data_override_allowed\\\",\\n    default=False,\\n)\\n\\n\\nasync def resolve_flow_data_override(current_user: UserRead, flow: FlowRead) -> bool:\\n    \\\"\\\"\\\"Resolve and remember whether this caller may override the stored graph.\\\"\\\"\\\"\\n    allowed = caller_owns_flow(flow, current_user)\\n    if not allowed:\\n        try:\\n            await ensure_flow_permission(\\n                current_user,\\n                FlowAction.WRITE,\\n                flow_id=flow.id,\\n                flow_user_id=flow.user_id,\\n                workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n                folder_id=getattr(flow, \\\"folder_id\\\", None),\\n            )\\n        except HTTPException:\\n            allowed = False\\n        else:\\n            allowed = True\\n    _flow_data_override_allowed.set(allowed)\\n    return allowed\\n\\n\\ndef flow_data_override_allowed() -> bool:\\n    \\\"\\\"\\\"Return the verdict resolved for the current request.\\\"\\\"\\\"\\n    return _flow_data_override_allowed.get()\\n\"}]}";
